-- Provider-independent football cache and notification state. Apply after comparing with production.
create table if not exists public.football_competitions (id bigint generated always as identity primary key, provider text not null, provider_id bigint not null, name text not null, country text, logo_url text, type text, enabled boolean not null default true, featured boolean not null default false, display_order integer not null default 100, raw_metadata jsonb not null default '{}', synced_at timestamptz, unique(provider,provider_id));
create table if not exists public.football_seasons (id bigint generated always as identity primary key, competition_id bigint not null references public.football_competitions(id) on delete cascade, season integer not null, current boolean not null default false, starts_on date, ends_on date, unique(competition_id,season));
create table if not exists public.football_teams (id bigint generated always as identity primary key, provider text not null, provider_id bigint not null, name text not null, code text, country text, badge_url text, venue jsonb, synced_at timestamptz, unique(provider,provider_id));
create table if not exists public.football_players (id bigint generated always as identity primary key, provider text not null, provider_id bigint not null, name text not null, photo_url text, nationality text, birth_date date, synced_at timestamptz, unique(provider,provider_id));
create table if not exists public.football_fixtures (id bigint generated always as identity primary key, provider text not null, provider_id bigint not null, competition_id bigint references public.football_competitions(id), season integer, home_team_id bigint references public.football_teams(id), away_team_id bigint references public.football_teams(id), kickoff_utc timestamptz not null, status_code text not null, elapsed integer, score jsonb not null default '{}', venue jsonb, referee text, round text, provider_updated_at timestamptz, synced_at timestamptz not null default now(), unique(provider,provider_id));
create table if not exists public.fixture_events (id bigint generated always as identity primary key, fixture_id bigint not null references public.football_fixtures(id) on delete cascade, provider_event_id text, fingerprint text not null, event_type text not null, detail text, team_provider_id bigint, player_provider_id bigint, elapsed integer, added_time integer, payload jsonb not null default '{}', created_at timestamptz not null default now(), unique(fixture_id,fingerprint));
create table if not exists public.fixture_statistics (fixture_id bigint not null references public.football_fixtures(id) on delete cascade, team_provider_id bigint not null, statistics jsonb not null, synced_at timestamptz not null default now(), primary key(fixture_id,team_provider_id));
create table if not exists public.fixture_lineups (fixture_id bigint not null references public.football_fixtures(id) on delete cascade, team_provider_id bigint not null, formation text, coach jsonb, starting_eleven jsonb not null default '[]', substitutes jsonb not null default '[]', synced_at timestamptz not null default now(), primary key(fixture_id,team_provider_id));
create table if not exists public.football_standings (competition_id bigint not null references public.football_competitions(id) on delete cascade, season integer not null, team_provider_id bigint not null, rank integer, played integer, wins integer, draws integer, losses integer, goals_for integer, goals_against integer, goal_difference integer, points integer, form text, synced_at timestamptz not null default now(), primary key(competition_id,season,team_provider_id));
create table if not exists public.provider_sync_state (resource_key text primary key, provider text not null, status text not null, last_attempt_at timestamptz, last_success_at timestamptz, last_live_update_at timestamptz, cursor jsonb, error_code text, error_message text);
create table if not exists public.provider_request_logs (id bigint generated always as identity primary key, provider text not null, endpoint text not null, cache_status text, response_status integer, duration_ms integer, quota_remaining integer, error_code text, requested_at timestamptz not null default now());
create table if not exists public.match_notification_subscriptions (user_id uuid not null references auth.users(id) on delete cascade, fixture_provider_id bigint not null, categories text[] not null default array['match_starting','goal','red_card','halftime','finished'], enabled boolean not null default true, created_at timestamptz not null default now(), primary key(user_id,fixture_provider_id));
create table if not exists public.processed_notification_events (fixture_provider_id bigint not null, fingerprint text not null, event_type text not null, deep_link text not null, processed_at timestamptz not null default now(), primary key(fixture_provider_id,fingerprint));
create table if not exists public.article_football_tags (article_id bigint not null, provider text not null, entity_type text not null check(entity_type in ('team','league','player')), provider_id bigint not null, created_at timestamptz not null default now(), primary key(article_id,provider,entity_type,provider_id));
create index if not exists fixtures_kickoff_idx on public.football_fixtures(kickoff_utc,status_code);
create index if not exists events_fixture_elapsed_idx on public.fixture_events(fixture_id,elapsed,added_time);
create index if not exists request_logs_time_idx on public.provider_request_logs(requested_at desc);
alter table public.match_notification_subscriptions enable row level security;
create policy "notification subscriptions owned" on public.match_notification_subscriptions for all using(auth.uid()=user_id) with check(auth.uid()=user_id);
alter table public.football_competitions enable row level security; alter table public.football_teams enable row level security; alter table public.football_players enable row level security; alter table public.football_fixtures enable row level security;
create policy "competitions public read" on public.football_competitions for select using(true);
create policy "teams public read" on public.football_teams for select using(true);
create policy "players public read" on public.football_players for select using(true);
create policy "fixtures public read" on public.football_fixtures for select using(true);
